    @SubscribeEvent
    public static void FillCreativeTabs(BuildCreativeModeTabContentsEvent event) {
        if (event.getTab() == MACreativeTabs.GENERAL) {
            List<Block> _excluded = Arrays.asList((Block)CIRCLE_OF_POWER.get(), (Block)EMPTY_FILLER_BLOCK.get(), (Block)HELLFIRE.get(), (Block)TRANSITORY_TILE.get(), (Block)SPECTRAL_ANVIL.get(), (Block)SPECTRAL_CRAFTING_TABLE.get(), (Block)SPECTRAL_LADDER.get(), (Block)SPECTRAL_STONECUTTER.get(), (Block)SPECTRAL_WEB.get(), (Block)SPECTRAL_FENCE.get(), (Block)MAGE_LIGHT.get(), (Block)ICE_SPIKE.get(), (Block)IMPALE_SPIKE.get(), (Block)STORM_CLOUD.get(), (Block)RITUAL_TELEPORT_DESTINATION.get(), (Block)POTTED_AUM.get(), (Block)POTTED_CERUBLOSSOM.get(), (Block)POTTED_DESERT_NOVA.get(), (Block)POTTED_TARMA_ROOT.get(), (Block)POTTED_WAKEBLOOM.get(), (Block)CHALK_RUNE.get(), (Block)FLUID_JUG.get(), (Block)FLUID_JUG_INFINITE_LAVA.get(), (Block)FLUID_JUG_INFINITE_WATER.get(), (Block)MANAWEAVE_CACHE.get(), (Block)WAKEBLOOM.get(), (Block)ARCANE_SENTRY.get(), (Block)EARTH_SENTRY.get(), (Block)ENDER_SENTRY.get(), (Block)WATER_SENTRY.get(), (Block)FIRE_SENTRY.get(), (Block)WIND_SENTRY.get(), (Block)REDSTONE_PULSE.get(), (Block)TRANSITORY_TUNNEL.get(), (Block)CLAY_MUG.get(), (Block)INVISIBLE_LIGHT_BLOCK.get());
            BLOCKS.getEntries().stream().map(x -> x.get()).filter(block -> !_excluded.contains(block)).forEach(block -> {
                ItemStack stack = new ItemStack((ItemLike)block);
                if (!stack.isEmpty() && stack.getCount() == 1) {
                    event.accept(stack);
                } else {
                    ManaAndArtifice.LOGGER.warn("unable to put " + block.toString() + " in the creative tab");
                }
            });
        }
    }
